import pickle
from taf.ul.auto_commissioning.data_storage.base import BasaDataStorage


class PythonDataStorage(BasaDataStorage):
    """Stores data of python format on hard drive"""

    def __init__(self, address):
        self.address = address

    def load(self):
        with open(self.address, 'rb') as f:
            return pickle.load(f)

    def save(self, data):
        with open(self.address, "wb") as f:
            pickle.dump(data, f, protocol=-1)
